using Microsoft.EntityFrameworkCore;
using System.Text;
namespace Decont;
public record OrganisationRow(string Username,string ManagerUsername,string Department,DateOnly From,DateOnly? To,bool Active);
public record OrganisationBatch(List<OrganisationRow> Rows,string InputHash,string SourceHash,string Reason);
public static class OrganisationImports {
 public static void ValidateSchedule(List<Assignment> rows){
  foreach(var group in rows.GroupBy(x=>x.UserId)){var periods=group.OrderBy(x=>x.From).ToList();for(int n=0;n<periods.Count;n++){Guard.Require(periods[n].From<=(periods[n].To??DateOnly.MaxValue),"dates","Perioadă invalidă.","Invalid period.");if(n>0)Guard.Require(periods[n-1].To!=null&&periods[n-1].To<periods[n].From,"overlap","Perioadele unui angajat se suprapun. Închide perioada existentă înainte de import.","Employee periods overlap. Close the existing period before importing.");}}
  foreach(var day in rows.Where(x=>x.Active).Select(x=>x.From).Distinct()){
   var graph=rows.Where(x=>x.Active&&x.From<=day&&(x.To==null||x.To>=day)).ToDictionary(x=>x.UserId,x=>x.ManagerId);
   var completed=new HashSet<string>();foreach(var start in graph.Keys){var cursor=start;var path=new HashSet<string>();while(graph.TryGetValue(cursor,out var next)&&!completed.Contains(cursor)){Guard.Require(path.Add(cursor),"manager_cycle","Importul creează un ciclu în organigramă. Verifică managerii și perioadele.","Import creates an organisation cycle. Check managers and dates.");cursor=next;}completed.UnionWith(path);}
  }
 }
 static async Task<List<Assignment>> Resolve(Db db,List<OrganisationRow> rows){
  Guard.Require(rows.Count is >0 and <=1000,"rows","Importul trebuie să aibă între 1 și 1.000 de rânduri.","Import must contain 1 to 1,000 rows.");var users=await db.Users.ToListAsync();var roles=await db.UserRoles.Join(db.Roles,x=>x.RoleId,y=>y.Id,(x,y)=>new{x.UserId,y.Name}).ToListAsync();var result=new List<Assignment>();
  foreach(var row in rows){var employee=users.SingleOrDefault(x=>string.Equals(x.UserName,row.Username,StringComparison.OrdinalIgnoreCase));var manager=users.SingleOrDefault(x=>string.Equals(x.UserName,row.ManagerUsername,StringComparison.OrdinalIgnoreCase));Guard.Require(employee!=null&&roles.Any(x=>x.UserId==employee.Id&&x.Name=="Employee")&&manager!=null&&manager.Active&&roles.Any(x=>x.UserId==manager.Id&&x.Name=="Manager"),"identity","Angajatul sau managerul nu există ori nu are rolul necesar. Verifică rândul importat.","Employee or manager is missing or lacks the required role. Check the imported row.");EmployeeIdentity.Format(employee!.Worker);Guard.Require(row.Department==""||await db.Masters.AnyAsync(x=>x.Kind=="organizationUnits"&&x.Code==row.Department&&x.Active),"department","Departamentul nu există în nomenclator.","Department is missing from master data.");result.Add(new(){UserId=employee.Id,ManagerId=manager!.Id,OrganizationCode=row.Department,From=row.From,To=row.To,Active=row.Active});}
  ValidateSchedule((await db.Assignments.ToListAsync()).Concat(result).ToList());return result;
 }
 public static void Map(RouteGroupBuilder api){var admin=api.MapGroup("/admin/organisation-import").RequireAuthorization(p=>p.RequireRole("Admin"));
  admin.MapGet("/template",()=>Results.File(Encoding.UTF8.GetBytes("username,managerUsername,department,from,to,active\r\n"),"text/csv","organisation-template.csv"));
  admin.MapGet("/export",async(Db db)=>{var users=await db.Users.ToDictionaryAsync(x=>x.Id,x=>x.UserName);var rows=await db.Assignments.OrderBy(x=>x.UserId).ThenBy(x=>x.From).ToListAsync();var csv="username,managerUsername,department,from,to,active\r\n"+string.Join("\r\n",rows.Select(x=>string.Join(",",new[]{users.GetValueOrDefault(x.UserId)??"",users.GetValueOrDefault(x.ManagerId)??"",x.OrganizationCode,x.From.ToString("yyyy-MM-dd"),x.To?.ToString("yyyy-MM-dd")??"",x.Active?"true":"false"}.Select(Csv.Cell))));return Results.File(Encoding.UTF8.GetBytes("\uFEFF"+csv),"text/csv","organisation-history.csv");});
  admin.MapPost("/preview",async(HttpContext c,Db db)=>{var(raw,sourceHash)=await SpreadsheetImports.Upload(c);Guard.Require(raw.Count is >1 and <=1001,"rows","Import gol sau prea mare: maximum 1.000 de rânduri.","Empty or oversized import: maximum 1,000 rows.");var required=new[]{"username","managerUsername","department","from","to","active"};Guard.Require(required.All(raw[0].Contains),"columns","Folosește șablonul de organigramă. Lipsesc coloane obligatorii.","Use the organisation template. Required columns are missing.");var rows=new List<OrganisationRow>();var errors=new List<object>();for(int n=1;n<raw.Count;n++){try{string Get(string key){var i=Array.IndexOf(raw[0],key);return i<raw[n].Length?raw[n][i].Trim():"";}Guard.Require(DateOnly.TryParseExact(Get("from"),"yyyy-MM-dd",out var from)&&(Get("to")==""||DateOnly.TryParseExact(Get("to"),"yyyy-MM-dd",out _))&&bool.TryParse(Get("active"),out _),"format","Folosește date YYYY-MM-DD și active true/false.","Use YYYY-MM-DD dates and active true/false.");rows.Add(new(Get("username"),Get("managerUsername"),Get("department"),from,Get("to")==""?null:DateOnly.ParseExact(Get("to"),"yyyy-MM-dd"),bool.Parse(Get("active"))));}catch(DomainException e){errors.Add(new{row=n+1,ro=e.Message,en=e.En});}}
   if(errors.Count==0)try{await Resolve(db,rows);}catch(DomainException e){errors.Add(new{row=0,ro=e.Message,en=e.En});}return new{rows,sourceHash,inputHash=Serialization.Hash(Serialization.Write(rows)),errors,count=rows.Count};
  });
  admin.MapPost("/confirm",async(OrganisationBatch i,Db db,Reports svc,HttpContext c)=>await Api.Atomic(db,c,i,async()=>{Guard.Reason(i.Reason);Guard.Require(i.SourceHash.Length==64&&i.InputHash==Serialization.Hash(Serialization.Write(i.Rows)),"import_changed","Importul s-a modificat. Repetă verificarea fișierului.","Import changed. Preview the file again.",409);var assignments=await Resolve(db,i.Rows);db.Assignments.AddRange(assignments);for(int n=0;n<assignments.Count;n++)svc.Log(c.User,null,assignments[n].Id.ToString(),"OrganisationImported",after:new{assignment=assignments[n],row=n+2,i.SourceHash,i.InputHash},reason:i.Reason);return new{count=assignments.Count};}));
 }
}
